// Generates .github/copilot-instructions.md from AGENTS.md so GitHub Copilot and
// other coding agents read one set of repository rules.
//
//   node scripts/sync-agent-instructions.js          rewrite the generated file
//   node scripts/sync-agent-instructions.js --check  fail when it is out of date
const fs = require("node:fs");
const path = require("node:path");

const projectRoot = path.resolve(__dirname, "..");
const sourcePath = path.join(projectRoot, "AGENTS.md");
const targetPath = path.join(projectRoot, ".github", "copilot-instructions.md");

const normalize = (text) => text.replace(/\r\n/g, "\n").trim();

function buildCopilotInstructions(agentsMarkdown) {
  const source = normalize(agentsMarkdown);
  const title = "# Repository guidance";
  if (!source.startsWith(title)) {
    throw new Error(`AGENTS.md must start with "${title}".`);
  }
  const sharedRules = source.slice(title.length).trim();
  return [
    "<!-- Generated from AGENTS.md by scripts/sync-agent-instructions.js. Do not edit this file. -->",
    "<!-- Change AGENTS.md, then run: pnpm run sync:instructions -->",
    "",
    "# GitHub Copilot instructions",
    "",
    sharedRules,
    "",
    "## Working in this repository with Copilot",
    "",
    "- Read `README.md`, then `docs/ARCHITECTURE.md`, `docs/DEVELOPMENT.md`, and `docs/TESTING.md` before changing behavior. Read the real files before editing them.",
    "- Detailed change rules live in `docs/DEVELOPMENT.md`. Path-scoped rules in `.github/instructions/` apply automatically to matching files.",
    "- Reusable task prompts live in `.github/prompts/` (for example `/verify-change` and `/prepare-release`).",
    "- Do not edit generated files: this file, `docs/RELEASE_UPDATE.md`, the generated PDFs, and versions synchronized from `config/app_version.json`.",
    "- The Copilot cloud agent runs on Linux. It can run `pnpm verify`, but not `pnpm run test:e2e` or `pnpm run dist`; state in the pull request when a change needs the Windows CI jobs to prove it.",
    "- Do not commit a user-guide PDF regenerated on Linux; its fonts differ from the Windows build.",
    ""
  ].join("\n");
}

function main() {
  const expected = buildCopilotInstructions(fs.readFileSync(sourcePath, "utf8"));
  if (process.argv.includes("--check")) {
    const actual = fs.existsSync(targetPath) ? fs.readFileSync(targetPath, "utf8") : "";
    if (normalize(actual) !== normalize(expected)) {
      console.error(".github/copilot-instructions.md is out of date with AGENTS.md. Run: pnpm run sync:instructions");
      process.exit(1);
    }
    console.log("Copilot instructions match AGENTS.md.");
    return;
  }
  fs.mkdirSync(path.dirname(targetPath), { recursive: true });
  fs.writeFileSync(targetPath, expected);
  console.log("Wrote .github/copilot-instructions.md from AGENTS.md.");
}

if (require.main === module) main();

module.exports = { buildCopilotInstructions };
